import React, { useEffect, useCallback } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { ArrowLeft, Star, Users, Settings2, MoreHorizontal } from "lucide-react";
import useBoardStore from "../context/BoardContext";
import { useAuth } from "../context/AuthContext";
import { useTheme } from "../context/ThemeContext";
import KanbanBoard from "../components/board/KanbanBoard";
import api from "../utils/api";

// ─── Board top bar ────────────────────────────────────────────────────────────
const BoardTopBar = ({ board, onStar, onBack }) => {
  const { toggleTheme, isDark } = useTheme();

  return (
    <div className="board-topbar">
      {/* Back */}
      <button className="btn-icon" onClick={onBack} title="Back to home">
        <ArrowLeft size={16} />
      </button>

      {/* Separator */}
      <div style={{ width: 1, height: 20, background: "rgba(255,255,255,.15)", flexShrink: 0 }} />

      {/* Board name */}
      <h1
        style={{
          fontSize: 15,
          fontWeight: 700,
          color: "#fff",
          margin: 0,
          flexShrink: 0,
          textShadow: "0 1px 3px rgba(0,0,0,.4)",
        }}
      >
        {board?.title}
      </h1>

      {/* Star */}
      <button
        className="btn-icon"
        onClick={onStar}
        title={board?.isStarred ? "Unstar board" : "Star board"}
        style={{ color: board?.isStarred ? "#fbbf24" : "rgba(255,255,255,.6)" }}
      >
        <Star size={15} fill={board?.isStarred ? "#fbbf24" : "none"} />
      </button>

      {/* Spacer */}
      <div style={{ flex: 1 }} />

      {/* Member avatars (up to 4) */}
      {board?.members && (
        <div style={{ display: "flex", alignItems: "center" }}>
          {board.members.slice(0, 4).map((m) => {
            const user = m.user;
            const colors = ["#8b5cf6","#6366f1","#0ea5e9","#10b981"];
            const color = user?.avatarColor || colors[Math.abs((user?.name || "").charCodeAt(0)) % 4];
            const initials = (user?.name || "?").split(" ").slice(0, 2).map((n) => n[0]).join("").toUpperCase();
            return (
              <div
                key={m.user?._id || Math.random()}
                title={user?.name}
                style={{
                  width: 28, height: 28, borderRadius: "50%",
                  background: color,
                  border: "2px solid rgba(255,255,255,.25)",
                  marginLeft: -6,
                  display: "flex", alignItems: "center", justifyContent: "center",
                  fontSize: 10, fontWeight: 700, color: "#fff",
                  flexShrink: 0,
                }}
              >
                {user?.avatar ? (
                  <img src={user.avatar} alt={user.name} style={{ width: "100%", height: "100%", objectFit: "cover", borderRadius: "50%" }} />
                ) : initials}
              </div>
            );
          })}
        </div>
      )}

      {/* Theme toggle */}
      <button
        className="theme-toggle"
        onClick={toggleTheme}
        title={isDark ? "Switch to light mode" : "Switch to dark mode"}
        style={{ background: "rgba(255,255,255,.12)", border: "1px solid rgba(255,255,255,.18)", color: "rgba(255,255,255,.8)" }}
      >
        {isDark ? "☀️" : "🌙"}
      </button>
    </div>
  );
};

// ─── Loading skeleton ─────────────────────────────────────────────────────────
const BoardSkeleton = () => (
  <div className="kanban-board">
    {[1, 2, 3].map((i) => (
      <div key={i} style={{ width: 296, flexShrink: 0 }}>
        <div style={{
          background: "var(--kanban-list-bg)",
          border: "1px solid var(--kanban-list-border)",
          borderRadius: "var(--radius-lg)",
          padding: 14,
          backdropFilter: "blur(12px)",
        }}>
          <div className="skeleton" style={{ height: 18, width: "60%", marginBottom: 16, borderRadius: 4 }} />
          {[1, 2, 3].map((j) => (
            <div key={j} className="skeleton" style={{ height: 72, marginBottom: 8, borderRadius: "var(--radius-md)" }} />
          ))}
        </div>
      </div>
    ))}
  </div>
);

// ─── BoardPage ────────────────────────────────────────────────────────────────
const BoardPage = () => {
  const { boardId } = useParams();
  const navigate = useNavigate();
  const { user } = useAuth();
  const { board, lists, isLoading, error, fetchBoard, reset } = useBoardStore();

  useEffect(() => {
    if (boardId) fetchBoard(boardId);
    return () => reset();
  }, [boardId]);

  const handleStar = useCallback(async () => {
    if (!board) return;
    try {
      await api.patch(`/boards/${boardId}`, { isStarred: !board.isStarred });
      await fetchBoard(boardId);
    } catch (err) {
      console.error("Failed to star board", err);
    }
  }, [board, boardId, fetchBoard]);

  if (error) {
    return (
      <div style={{ display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", height: "100%", gap: 12 }}>
        <p style={{ fontSize: 16, color: "var(--accent-rose)" }}>⚠ {error}</p>
        <button className="btn btn-ghost" onClick={() => navigate("/")}>
          <ArrowLeft size={14} /> Go home
        </button>
      </div>
    );
  }

  return (
    <div style={{ display: "flex", flexDirection: "column", height: "100%", overflow: "hidden" }}>
      {/* Top bar */}
      <BoardTopBar
        board={board}
        onStar={handleStar}
        onBack={() => navigate("/")}
      />

      {/* Board canvas */}
      <div style={{ flex: 1, overflow: "hidden", minHeight: 0 }}>
        {isLoading ? (
          <BoardSkeleton />
        ) : (
          <KanbanBoard
            boardId={boardId}
            board={board}
            currentUser={user}
          />
        )}
      </div>
    </div>
  );
};

export default BoardPage;
